// ---- Project: File Organizer CLI ----

// A CLI tool that organizes files in a directory
// Features:
// 1. Scan a directory for files
// 2. Group files by extension
// 3. Create subdirectories for each extension
// 4. Move files to the appropriate subdirectory

use std::fs;
use std::path::{Path, PathBuf};
use std::collections::HashMap;

// ---- Configuration ----
struct Config {
    source_dir: PathBuf,
    verbose: bool,
    dry_run: bool,
}

impl Config {
    fn new(source_dir: PathBuf, verbose: bool, dry_run: bool) -> Self {
        Config {
            source_dir,
            verbose,
            dry_run,
        }
    }
}

// ---- File organizer ----
struct FileOrganizer {
    config: Config,
}

impl FileOrganizer {
    fn new(config: Config) -> Self {
        FileOrganizer { config }
    }

    fn run(&self) -> Result<(), Box<dyn std::error::Error>> {
        if self.config.verbose {
            println!("Organizing files in: {:?}", self.config.source_dir);
            if self.config.dry_run {
                println!("Dry run mode: No files will be moved");
            }
        }

        // Scan directory
        let files = self.scan_directory()?;

        if files.is_empty() {
            println!("No files found in {:?}", self.config.source_dir);
            return Ok(());
        }

        // Group by extension
        let groups = self.group_by_extension(&files);

        // Display groups
        self.display_groups(&groups);

        // Create directories and move files
        if !self.config.dry_run {
            self.organize_files(&groups)?;
        }

        Ok(())
    }

    fn scan_directory(&self) -> Result<Vec<PathBuf>, Box<dyn std::error::Error>> {
        let mut files = Vec::new();
        let entries = fs::read_dir(&self.config.source_dir)?;

        for entry in entries {
            let entry = entry?;
            let path = entry.path();

            if path.is_file() {
                files.push(path);
            }
        }

        Ok(files)
    }

    fn group_by_extension(&self, files: &[PathBuf]) -> HashMap<String, Vec<PathBuf>> {
        let mut groups: HashMap<String, Vec<PathBuf>> = HashMap::new();

        for file in files {
            let extension = file
                .extension()
                .and_then(|e| e.to_str())
                .unwrap_or("no_extension")
                .to_string();

            groups.entry(extension).or_insert_with(Vec::new).push(file.clone());
        }

        groups
    }

    fn display_groups(&self, groups: &HashMap<String, Vec<PathBuf>>) {
        println!("\n=== File Groups ===");
        for (ext, files) in groups {
            println!("  .{}: {} files", ext, files.len());
            if self.config.verbose {
                for file in files {
                    println!("    - {}", file.file_name().unwrap().to_string_lossy());
                }
            }
        }
    }

    fn organize_files(&self, groups: &HashMap<String, Vec<PathBuf>>) -> Result<(), Box<dyn std::error::Error>> {
        for (ext, files) in groups {
            let dir = self.config.source_dir.join(ext);

            // Create directory
            if !dir.exists() {
                fs::create_dir(&dir)?;
                if self.config.verbose {
                    println!("Created directory: {:?}", dir);
                }
            }

            // Move files
            for file in files {
                let dest = dir.join(file.file_name().unwrap());
                fs::rename(file, &dest)?;
                if self.config.verbose {
                    println!("Moved: {:?} -> {:?}", file, dest);
                }
            }
        }

        Ok(())
    }
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let args: Vec<String> = std::env::args().collect();

    let source_dir = args.get(1)
        .map(PathBuf::from)
        .unwrap_or_else(|| PathBuf::from("."));

    let verbose = args.contains(&"-v".to_string()) || args.contains(&"--verbose".to_string());
    let dry_run = args.contains(&"-n".to_string()) || args.contains(&"--dry-run".to_string());

    let config = Config::new(source_dir, verbose, dry_run);
    let organizer = FileOrganizer::new(config);

    organizer.run()?;

    Ok(())
}

